local ADDON_NAME, ns = ...

---------------------------------------------------------------------------
-- Starter data (beta nodes)
--   Data\StarterData.lua is generated by tools/export_starter.py from
--   collected SavedVariables. Each new data version is imported once.
--   Imported nodes are marked source = "starter". They become normal nodes
--   once we harvest them. Nodes nobody confirms expire after EXPIRE_DAYS,
--   so wrong beta positions clean themselves up after launch.
---------------------------------------------------------------------------
local EXPIRE_DAYS = 21
local MERGE_RADIUS = 10 -- yards, same as the recorder
local TYPES = { h = "herb", o = "ore", c = "chest" }

local function Confirmed(n)
    return n.source ~= "starter" or (n.heard or 0) >= 1
end

-- Removes starter nodes that nobody confirmed in time
local function ExpireOld()
    local limit = time() - EXPIRE_DAYS * 86400
    local removed = 0
    for _, list in pairs(ns.db.nodes) do
        for i = #list, 1, -1 do
            local n = list[i]
            if n.source == "starter" and not Confirmed(n) and (n.added or 0) < limit then
                table.remove(list, i)
                removed = removed + 1
            end
        end
    end
    if removed > 0 then
        ns.Print(("Removed %d old beta nodes nobody confirmed."):format(removed))
        ns.NotifyNodesChanged()
    end
end

local function Import(data)
    local now, added, known = time(), 0, 0
    for mapID, list in pairs(data.nodes or {}) do
        ns.db.nodes[mapID] = ns.db.nodes[mapID] or {}
        for _, e in ipairs(list) do
            local id, t, x, y, item, reporters, name = unpack(e)
            x, y = x / 10000, y / 10000
            if ns.FindNode(mapID, id, x, y, MERGE_RADIUS) then
                known = known + 1
            else
                local node = {
                    id = id, type = TYPES[t], name = name or id,
                    x = x, y = y, count = reporters or 1,
                    item = (item and item > 0) and item or nil,
                    source = "starter", added = now, last = now,
                }
                table.insert(ns.db.nodes[mapID], node)
                ns.NotifyNodesChanged("add", mapID, node)
                added = added + 1
            end
        end
    end
    ns.db.starterVersion = data.version
    ns.Print(("Beta data %s: %d nodes added, %d already known."):format(
        tostring(data.version), added, known))
end

local loader = CreateFrame("Frame")
loader:RegisterEvent("PLAYER_LOGIN")
loader:SetScript("OnEvent", function()
    local data = GathercraftStarterData
    if data and data.version and ns.db.starterVersion ~= data.version then
        Import(data)
    end
    ExpireOld()
end)
